import{_ as n,l as i,o as e,c as s,v as t,p as l,x as o,d,i as _,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"复合与选择者期权","description":"","frontmatter":{"title":"复合与选择者期权","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/compound-chooser.md","filePath":"quant/compound-chooser.md","lastUpdated":1789023840000}'),h={name:"quant/compound-chooser.md"};function u(E,a,c,m,B,f){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="复合与选择者期权" tabindex="-1">复合与选择者期权 <a class="header-anchor" href="#复合与选择者期权" aria-label="Permalink to &quot;复合与选择者期权&quot;">​</a></h1><div class="epigraph"><p>复合期权是期权上的期权；选择者在未来某日才决定要看涨还是看跌。两者都把「今天还没选定的权利」标成可交易状态。</p><footer>—— Geske, The Valuation of Compound Options, Journal of Financial Economics, 1979；Rubinstein, Options for the Undecided, Risk, 1991</footer></div><p><a href="/quant/correlation-swap">上一课</a>把多资产相关收成互换。本课回到单资产，但把<strong>权利本身</strong>再期权化：复合看涨是在 \\(t_1\\) 用执行价 \\(K_1\\) 买入一份到期 \\(T\\)、执行价 \\(K_2\\) 的香草；选择者在 \\(t_1\\) 于看涨与看跌之间二选一。缺口不是再推 <a href="/quant/bsm">BSM</a>，而是二维正态与「选择日」上的临界现价。后课才把这些零件组装进权证与结构票据。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公司债、权证、雇员期权、可转债里经常嵌着「先有权再买期权」：股权本身可看成公司资产上的期权，再在其上写期权就是 Geske 的复合。选择者则出现在结构票据的「到期前决定方向」。问题是：复合价格依赖标的在 \\(t_1\\) 是否越过临界值 \\(S^*\\)（使内层期权价值等于 \\(K_1\\)），因此出现二维累积正态，而不是把两份香草相乘。把复合当「杠杆香草」用更高 Vega 去套，会漏掉 \\(t_1\\) 附近对临界值的数字风险。</p><p>选择者在 \\(t_1\\) 的最优决策几乎总是：选当时更贵的那一侧，价值等于 \\(\\max(C,P)\\)，再用看跌看涨平价化成香草加现金。简单选择者因而有闭式；复杂选择者（可在区间内任意时刻选）没有。</p><h3 id="是内层期权的隐含执行价" tabindex="-1">\\(S^*\\) 是内层期权的隐含执行价 <a class="header-anchor" href="#是内层期权的隐含执行价" aria-label="Permalink to &quot;$S^*$ 是内层期权的隐含执行价&quot;">​</a></h3><p>Geske 把外层行权条件写成 \\(C(S_{t_1};K_2,T-t_1)=K_1\\)，反解 \\(S^*\\)。外层看涨于是像执行价为 \\(S^*\\) 的数字叠加内层香草。数值上要对 \\(S^*\\) 做一维根搜索，再送入二维正态；\\(\\sigma\\) 一变，\\(S^*\\) 也变，Vega 不能只对内层香草取。</p><p><span class="marginnote">Geske 复合与公司债的结构性模型同源：股权是资产上的看涨，认股权证是股权上的看涨。本课停在期权公式；<a href="/quant/merton-structural">Merton 结构模型</a> 不在这里重写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>欧式复合：Geske 二维正态，注意看涨上看涨、看涨上看跌等四种的符号与 \\(S^*\\)。欧式简单选择者：Rubinstein 闭式，本质是 \\(t_1\\) 处 \\(\\max(C,P)\\)。美式、离散分红、微笑：闭式作废，用树或 <a href="/quant/option-pde">PDE</a> 在选择日对 \\(\\max(C,P)\\) 取边界，或对复合在 \\(t_1\\) 比较内层价值与 \\(K_1\\)。</p><p>有微笑时，内层期权必须用与市场一致的边际，外层再用同一模型走到 \\(t_1\\)。用两张不同的 BSM 隐波分别给内外层，会破坏 \\(t_1\\) 处的无套利衔接。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>复合把时间切成两段：先决定是否支付 \\(K_1\\) 买入剩余香草，再走内层。信息在 \\(t_1\\) 被「行权或放弃」离散化，故出现临界现价与数字风险。选择者把方向选择推迟到 \\(t_1\\)，等价于持有一个在 \\(t_1\\) 变成香草的或有要求权；推迟本身有价值，因为 \\(t_1\\) 之前不必承诺 Delta 的符号。</p>',14)),(e(),l(p,null,{default:o(()=>[_(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Comp%5B%22%E5%A4%8D%E5%90%88%20%E6%9C%9F%E6%9D%83%E4%B8%8A%E7%9A%84%E6%9C%9F%E6%9D%83%22%5D%20--%3E%20Sstar%5B%22t1%20%E4%B8%B4%E7%95%8C%E7%8E%B0%E4%BB%B7%20S*%22%5D%0A%20%20Sstar%20--%3E%20Binorm%5B%22%E4%BA%8C%E7%BB%B4%E6%AD%A3%E6%80%81%20Geske%22%5D%0A%20%20Ch%5B%22%E9%80%89%E6%8B%A9%E8%80%85%20%E6%9C%AA%E6%9D%A5%E6%89%8D%E9%80%89%E6%B6%A8%E6%88%96%E8%B7%8C%22%5D%20--%3E%20MaxCP%5B%22t1%20%E5%8F%96%20max%20C%20P%22%5D%0A%20%20MaxCP%20--%3E%20Rub%5B%22%E7%AE%80%E5%8D%95%E9%80%89%E6%8B%A9%E8%80%85%E6%9C%89%E9%97%AD%E5%BC%8F%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>二维正态假设 GBM、常数 \\(\\sigma\\)。利率随机、信用风险、提前行权都会让 Geske 变成近似。可转债里的转股权是复合的近亲，但叠加赎回、下修与信用，见 <a href="/quant/convertible-credit">可转债与信用</a>，本课不写转债条款。</p><p>不要把选择者当「免费的跨式」。你付的是推迟方向决策的权利金；到期两边都赚的路径并不存在。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复合期权在 \\(t_1\\) 有临界现价 \\(S^*\\)，价格是二维正态，不是两份香草相乘。</li><li>简单选择者在选择日取 \\(\\max(C,P)\\)，有 Rubinstein 闭式。</li><li>微笑下内外层必须同一模型衔接。</li><li>出处：Geske, <em>JFE</em>, 1979；Rubinstein, <em>Risk</em>, 1991。</li></ul>',5))])}const S=n(h,[["render",u]]);export{A as __pageData,S as default};
